import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';

export interface Movie {
  id: number;
  title: string;
  genre: string;
  runtimeMinutes: number;
  format: 'PL dubbing' | 'PL subtitles';
}

export interface Screening {
  id: number;
  movieId: number;
  date: string;
  time: string;
  occupiedSeats: string[];
}

export interface ReservationRequest {
  screeningId: number;
  seats: string[];
  customer: {
    firstName: string;
    lastName: string;
    email: string;
    phone: string;
  };
  totalPrice: number;
}

export interface Reservation extends ReservationRequest {
  id: number;
}

const BASE_URL = 'http://localhost:3000';

@Injectable({ providedIn: 'root' })
export class CinemaApi {
  private readonly http = inject(HttpClient);

  movies(): Observable<Movie[]> {
    return this.http.get<Movie[]>(`${BASE_URL}/movies`);
  }

  movie(id: number): Observable<Movie> {
    return this.http.get<Movie>(`${BASE_URL}/movies/${id}`);
  }

  screenings(date: string): Observable<Screening[]> {
    return this.http.get<Screening[]>(`${BASE_URL}/screenings`, { params: { date } });
  }

  screening(id: number): Observable<Screening> {
    return this.http.get<Screening>(`${BASE_URL}/screenings/${id}`);
  }

  createReservation(body: ReservationRequest): Observable<Reservation> {
    return this.http.post<Reservation>(`${BASE_URL}/reservations`, body);
  }
}

import { Injectable, signal } from '@angular/core';

export interface CustomerForm {
  firstName: string;
  lastName: string;
  email: string;
  confirmEmail: string;
  phone: string;
  terms: boolean;
}

export interface Booking {
  screeningId: number;
  seats: string[];
  form: CustomerForm;
  paidEmail: string | null;
}

const STORAGE_KEY = 'cinescope.booking';

export function emptyForm(): CustomerForm {
  return { firstName: '', lastName: '', email: '', confirmEmail: '', phone: '', terms: false };
}

@Injectable({ providedIn: 'root' })
export class BookingService {
  readonly booking = signal<Booking | null>(this.read());

  save(booking: Booking): void {
    sessionStorage.setItem(STORAGE_KEY, JSON.stringify(booking));
    this.booking.set(booking);
  }

  clear(): void {
    sessionStorage.removeItem(STORAGE_KEY);
    this.booking.set(null);
  }

  private read(): Booking | null {
    const raw = sessionStorage.getItem(STORAGE_KEY);
    return raw ? (JSON.parse(raw) as Booking) : null;
  }
}

const WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

export function toIsoDate(date: Date): string {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}

export function todayIso(): string {
  return toIsoDate(new Date());
}

export function isoToDate(iso: string): Date {
  const [y, m, d] = iso.split('-').map(Number);
  return new Date(y, m - 1, d);
}

export function isValidIsoDate(value: string | null): value is string {
  if (!value || !/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    return false;
  }
  return toIsoDate(isoToDate(value)) === value;
}

export function addDays(iso: string, days: number): string {
  const date = isoToDate(iso);
  date.setDate(date.getDate() + days);
  return toIsoDate(date);
}

export function weekdayName(iso: string): string {
  return WEEKDAYS[isoToDate(iso).getDay()];
}

export function showDate(iso: string, time: string): string {
  const date = isoToDate(iso);
  return `${WEEKDAYS[date.getDay()]} ${date.getDate()} ${MONTHS[date.getMonth()]} ${time}`;
}

export function formatPrice(amount: number): string {
  return `${amount.toFixed(2)} PLN`;
}

export const MAX_SEATS = 10;
export const COLUMNS = 24;
export const ROWS = 15;

export interface SeatRef {
  row: number;
  column: number;
}

export interface Unit {
  row: number;
  columns: number[];
  ids: string[];
  price: number;
  isCouch: boolean;
}

export function seatId(row: number, column: number): string {
  return `R${row}C${column}`;
}

export function parseSeatId(id: string): SeatRef {
  const [, row, column] = /^R(\d+)C(\d+)$/.exec(id) ?? [];
  return { row: Number(row), column: Number(column) };
}

export function couchStart(column: number): number {
  return column % 2 === 1 ? column : column - 1;
}

export function firstColumn(row: number): number {
  return row <= 10 ? 5 : 1;
}

export function isAccessible(row: number, column: number): boolean {
  return row === 1 && column >= 10 && column <= 15;
}

export function priceOf(row: number): number {
  if (row <= 5) {
    return 25;
  }
  if (row <= 10) {
    return 32;
  }
  if (row <= 14) {
    return 39;
  }
  return 89;
}

export function groupIntoUnits(ids: string[]): Unit[] {
  const sorted = [...ids]
    .map((id) => ({ id, ...parseSeatId(id) }))
    .sort((a, b) => a.row - b.row || a.column - b.column);
  const units: Unit[] = [];
  for (const { id, row, column } of sorted) {
    if (row === ROWS) {
      const start = couchStart(column);
      const last = units[units.length - 1];
      if (last?.isCouch && last.row === row && last.columns[0] === start) {
        last.ids.push(id);
        last.columns.push(column);
      } else {
        units.push({ row, columns: [column], ids: [id], price: priceOf(row), isCouch: true });
      }
    } else {
      units.push({ row, columns: [column], ids: [id], price: priceOf(row), isCouch: false });
    }
  }
  return units;
}

export function unitLabel(unit: Unit): string {
  if (!unit.isCouch) {
    return String(unit.columns[0]);
  }
  return unit.columns.length === 2 ? `${unit.columns[0]}-${unit.columns[1]}` : String(unit.columns[0]);
}

import { Component, inject } from '@angular/core';
import { MAT_SNACK_BAR_DATA, MatSnackBar, MatSnackBarRef } from '@angular/material/snack-bar';
import { Injectable, inject as injectFn } from '@angular/core';

export const TOAST_DURATION_MS = 4000;

@Component({
  selector: 'app-toast',
  template: `<div class="toast" data-testid="toast">{{ message }}</div>`,
  styles: `
    .toast {
      font-size: 14px;
    }
  `,
})
export class ToastComponent {
  readonly message = inject<string>(MAT_SNACK_BAR_DATA);
  readonly ref = inject<MatSnackBarRef<ToastComponent>>(MatSnackBarRef);
}

@Injectable({ providedIn: 'root' })
export class ToastService {
  private readonly snackBar = injectFn(MatSnackBar);

  show(message: string): void {
    this.snackBar.openFromComponent(ToastComponent, {
      data: message,
      duration: TOAST_DURATION_MS,
    });
  }
}

import { ApplicationConfig, provideBrowserGlobalErrorListeners } from '@angular/core';
import { provideHttpClient } from '@angular/common/http';
import { provideNativeDateAdapter } from '@angular/material/core';
import { provideRouter } from '@angular/router';
import { appRoutes } from './app.routes';

export const appConfig: ApplicationConfig = {
  providers: [
    provideBrowserGlobalErrorListeners(),
    provideRouter(appRoutes),
    provideHttpClient(),
    provideNativeDateAdapter(),
  ],
};

import { Route } from '@angular/router';
import { MovieListComponent } from './movies/movie-list.component';
import { SeatMapComponent } from './seats/seat-map.component';
import { SummaryComponent } from './summary/summary.component';
import { CheckoutComponent } from './checkout/checkout.component';
import { ConfirmationComponent } from './confirmation/confirmation.component';
import { bookingInProgressGuard, bookingPaidGuard } from './core/guards';

export const appRoutes: Route[] = [
  { path: '', component: MovieListComponent },
  { path: 'screenings/:id/seats', component: SeatMapComponent },
  { path: 'screenings/:id/summary', component: SummaryComponent, canActivate: [bookingInProgressGuard] },
  { path: 'screenings/:id/checkout', component: CheckoutComponent, canActivate: [bookingInProgressGuard] },
  { path: 'confirmation', component: ConfirmationComponent, canActivate: [bookingPaidGuard] },
  { path: '**', redirectTo: '' },
];

import { inject } from '@angular/core';
import { CanActivateFn, Router } from '@angular/router';
import { BookingService } from './booking';

export const bookingInProgressGuard: CanActivateFn = (route) => {
  const booking = inject(BookingService).booking();
  const screeningId = Number(route.paramMap.get('id'));
  if (booking && !booking.paidEmail && booking.screeningId === screeningId && booking.seats.length > 0) {
    return true;
  }
  return inject(Router).createUrlTree(['/']);
};

export const bookingPaidGuard: CanActivateFn = () => {
  const booking = inject(BookingService).booking();
  if (booking?.paidEmail) {
    return true;
  }
  return inject(Router).createUrlTree(['/']);
};

import { Component, Injectable, inject } from '@angular/core';
import { MAT_SNACK_BAR_DATA, MatSnackBar } from '@angular/material/snack-bar';

export const TOAST_DURATION_MS = 4000;

@Component({
  selector: 'app-toast',
  template: `<div data-testid="toast">{{ message }}</div>`,
})
export class ToastComponent {
  readonly message = inject<string>(MAT_SNACK_BAR_DATA);
}

@Injectable({ providedIn: 'root' })
export class ToastService {
  private readonly snackBar = inject(MatSnackBar);

  show(message: string): void {
    this.snackBar.openFromComponent(ToastComponent, {
      data: message,
      duration: TOAST_DURATION_MS,
    });
  }
}

import { Component, computed, inject } from '@angular/core';
import { takeUntilDestroyed, toObservable, toSignal } from '@angular/core/rxjs-interop';
import { MatButtonModule } from '@angular/material/button';
import { MatDatepickerModule } from '@angular/material/datepicker';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { ActivatedRoute, Router } from '@angular/router';
import { catchError, combineLatest, concat, forkJoin, map, of, startWith, Subject, switchMap } from 'rxjs';
import { CinemaApi, Movie, Screening } from '../core/api';
import { addDays, isValidIsoDate, isoToDate, toIsoDate, todayIso, weekdayName } from '../core/format';

interface MovieCard {
  movie: Movie;
  screenings: Screening[];
}

type MovieListView =
  | { status: 'loading' }
  | { status: 'error' }
  | { status: 'ready'; cards: MovieCard[] };

@Component({
  selector: 'app-movie-list',
  imports: [MatButtonModule, MatDatepickerModule, MatFormFieldModule, MatInputModule],
  templateUrl: './movie-list.component.html',
  styleUrl: './movie-list.component.scss',
})
export class MovieListComponent {
  private readonly api = inject(CinemaApi);
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);
  private readonly retry$ = new Subject<void>();

  protected readonly today = new Date();
  protected readonly dayButtons = computed(() => {
    const today = todayIso();
    return [0, 1, 2, 3, 4].map((offset) => {
      const iso = addDays(today, offset);
      return { iso, label: offset === 0 ? 'Today' : weekdayName(iso) };
    });
  });

  private readonly queryDate = toSignal(this.route.queryParamMap.pipe(map((params) => params.get('date'))), {
    requireSync: true,
  });

  protected readonly date = computed(() => {
    const raw = this.queryDate();
    const today = todayIso();
    return isValidIsoDate(raw) && raw >= today ? raw : today;
  });

  protected readonly pickerValue = computed(() => {
    const date = this.date();
    return this.dayButtons().some((day) => day.iso === date) ? null : isoToDate(date);
  });

  protected readonly view = toSignal(
    combineLatest([toObservable(this.date), this.retry$.pipe(startWith(undefined))]).pipe(
      switchMap(([date]) => this.load(date)),
    ),
    { initialValue: { status: 'loading' } as MovieListView },
  );

  protected readonly loading = computed(() => this.view().status === 'loading');

  protected retry(): void {
    this.retry$.next();
  }

  protected selectDay(iso: string): void {
    void this.router.navigate([], { relativeTo: this.route, queryParams: { date: iso } });
  }

  protected onPicked(value: Date | null): void {
    if (value && !Number.isNaN(value.getTime())) {
      this.selectDay(toIsoDate(value));
    }
  }

  protected openScreening(id: number): void {
    void this.router.navigate(['/screenings', id, 'seats']);
  }

  protected readonly minDate = isoToDate(todayIso());

  private load(date: string) {
    const loaded = forkJoin({
      movies: this.api.movies(),
      screenings: this.api.screenings(date),
    }).pipe(
      map(({ movies, screenings }): MovieListView => ({
        status: 'ready',
        cards: this.toCards(movies, screenings, date),
      })),
      catchError(() => of<MovieListView>({ status: 'error' })),
    );
    return concat(of<MovieListView>({ status: 'loading' }), loaded);
  }

  private toCards(movies: Movie[], screenings: Screening[], date: string): MovieCard[] {
    return movies
      .map((movie) => ({
        movie,
        screenings: screenings
          .filter((s) => s.movieId === movie.id && s.date === date)
          .sort((a, b) => a.time.localeCompare(b.time)),
      }))
      .filter((card) => card.screenings.length > 0);
  }
}

