import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';

export interface Movie {
  id: number;
  title: string;
  genre: string;
  runtimeMinutes: number;
  format: 'PL dubbing' | 'PL subtitles';
}

export interface Screening {
  id: number;
  movieId: number;
  date: string;
  time: string;
  occupiedSeats: string[];
}

export interface ReservationRequest {
  screeningId: number;
  seats: string[];
  customer: {
    firstName: string;
    lastName: string;
    email: string;
    phone: string;
  };
  totalPrice: number;
}

export interface Reservation extends ReservationRequest {
  id: number;
}

const BASE_URL = 'http://localhost:3000';

@Injectable({ providedIn: 'root' })
export class CinemaApi {
  private readonly http = inject(HttpClient);

  movies(): Observable<Movie[]> {
    return this.http.get<Movie[]>(`${BASE_URL}/movies`);
  }

  movie(id: number): Observable<Movie> {
    return this.http.get<Movie>(`${BASE_URL}/movies/${id}`);
  }

  screenings(date: string): Observable<Screening[]> {
    return this.http.get<Screening[]>(`${BASE_URL}/screenings`, { params: { date } });
  }

  screening(id: number): Observable<Screening> {
    return this.http.get<Screening>(`${BASE_URL}/screenings/${id}`);
  }

  createReservation(body: ReservationRequest): Observable<Reservation> {
    return this.http.post<Reservation>(`${BASE_URL}/reservations`, body);
  }
}

import { Injectable, signal } from '@angular/core';

export interface CustomerForm {
  firstName: string;
  lastName: string;
  email: string;
  confirmEmail: string;
  phone: string;
  terms: boolean;
}

export interface Booking {
  screeningId: number;
  seats: string[];
  form: CustomerForm;
  paidEmail: string | null;
}

const STORAGE_KEY = 'cinescope.booking';

export function emptyForm(): CustomerForm {
  return { firstName: '', lastName: '', email: '', confirmEmail: '', phone: '', terms: false };
}

@Injectable({ providedIn: 'root' })
export class BookingService {
  readonly booking = signal<Booking | null>(this.read());

  save(booking: Booking): void {
    sessionStorage.setItem(STORAGE_KEY, JSON.stringify(booking));
    this.booking.set(booking);
  }

  clear(): void {
    sessionStorage.removeItem(STORAGE_KEY);
    this.booking.set(null);
  }

  private read(): Booking | null {
    const raw = sessionStorage.getItem(STORAGE_KEY);
    return raw ? (JSON.parse(raw) as Booking) : null;
  }
}

const WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

export function toIsoDate(date: Date): string {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}

export function todayIso(): string {
  return toIsoDate(new Date());
}

export function isoToDate(iso: string): Date {
  const [y, m, d] = iso.split('-').map(Number);
  return new Date(y, m - 1, d);
}

export function isValidIsoDate(value: string | null): value is string {
  if (!value || !/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    return false;
  }
  return toIsoDate(isoToDate(value)) === value;
}

export function addDays(iso: string, days: number): string {
  const date = isoToDate(iso);
  date.setDate(date.getDate() + days);
  return toIsoDate(date);
}

export function weekdayName(iso: string): string {
  return WEEKDAYS[isoToDate(iso).getDay()];
}

export function showDate(iso: string, time: string): string {
  const date = isoToDate(iso);
  return `${WEEKDAYS[date.getDay()]} ${date.getDate()} ${MONTHS[date.getMonth()]} ${time}`;
}

export function formatPrice(amount: number): string {
  return `${amount.toFixed(2)} PLN`;
}

export const MAX_SEATS = 10;
export const COLUMNS = 24;
export const ROWS = 15;

export interface SeatRef {
  row: number;
  column: number;
}

export interface Unit {
  row: number;
  columns: number[];
  ids: string[];
  price: number;
  isCouch: boolean;
}

export function seatId(row: number, column: number): string {
  return `R${row}C${column}`;
}

export function parseSeatId(id: string): SeatRef {
  const [, row, column] = /^R(\d+)C(\d+)$/.exec(id) ?? [];
  return { row: Number(row), column: Number(column) };
}

export function couchStart(column: number): number {
  return column % 2 === 1 ? column : column - 1;
}

export function firstColumn(row: number): number {
  return row <= 10 ? 5 : 1;
}

export function isAccessible(row: number, column: number): boolean {
  return row === 1 && column >= 10 && column <= 15;
}

export function priceOf(row: number): number {
  if (row <= 5) {
    return 25;
  }
  if (row <= 10) {
    return 32;
  }
  if (row <= 14) {
    return 39;
  }
  return 89;
}

export function groupIntoUnits(ids: string[]): Unit[] {
  const sorted = [...ids]
    .map((id) => ({ id, ...parseSeatId(id) }))
    .sort((a, b) => a.row - b.row || a.column - b.column);
  const units: Unit[] = [];
  for (const { id, row, column } of sorted) {
    if (row === ROWS) {
      const start = couchStart(column);
      const last = units[units.length - 1];
      if (last?.isCouch && last.row === row && last.columns[0] === start) {
        last.ids.push(id);
        last.columns.push(column);
      } else {
        units.push({ row, columns: [column], ids: [id], price: priceOf(row), isCouch: true });
      }
    } else {
      units.push({ row, columns: [column], ids: [id], price: priceOf(row), isCouch: false });
    }
  }
  return units;
}

export function unitLabel(unit: Unit): string {
  if (!unit.isCouch) {
    return String(unit.columns[0]);
  }
  return unit.columns.length === 2 ? `${unit.columns[0]}-${unit.columns[1]}` : String(unit.columns[0]);
}

import { Component, inject } from '@angular/core';
import { MAT_SNACK_BAR_DATA, MatSnackBar, MatSnackBarRef } from '@angular/material/snack-bar';
