  }
  return inject(Router).createUrlTree(['/']);
};

export const bookingPaidGuard: CanActivateFn = () => {
  const booking = inject(BookingService).booking();
  if (booking?.paidEmail) {
    return true;
  }
  return inject(Router).createUrlTree(['/']);
};

